

import Link from 'next/link'
import { FaEdit, FaTrash } from 'react-icons/fa'
import Button from '../button'
export default function NewsList({ news, onEdit, onDelete }) {
  return (
    <ul className="news-list">
      {news.map(newsItem => (
        <li key={newsItem.id} className="news-item">
          {/* Overlay buttons */}
          <div className="news-actions">
            <Button
              className="edit-btn"
              Click={e => {
                e.preventDefault()
                e.stopPropagation()
                onEdit(newsItem)
              }}
            >
              <FaEdit />
            </Button>

            <Button
              className="delete-btn"
              Click={e => {
                e.preventDefault()
                e.stopPropagation()
                onDelete(newsItem)
              }}
            >
              <FaTrash />
            </Button>
          </div>

          <Link href={`/news/${newsItem.slug}`} className="news-link">
            <img
              src={`${process.env.NEXT_PUBLIC_API_URL}/uploads/${newsItem.image}`}
              alt={newsItem.title}
            />
            <span>{newsItem.title}</span>
          </Link>
        </li>
      ))}
    </ul>
  )
}
